import fs from'node:fs';import crypto from'node:crypto';import zlib from'node:zlib';
const path=new URL('../research/all-parameter-audit.json',import.meta.url),raw=fs.readFileSync(path),x=JSON.parse(raw),compressed=zlib.gzipSync(raw,{mtime:0}),groups={};
for(const r of x.rows){const key=r.source+'/'+r.group,g=groups[key]??={total:0,locked:0,responding:0,withoutResponse:[]};g.total++;g.locked+=Number(!!r.locked);g.responding+=Number(!!r.response);if(!r.locked&&!r.response)g.withoutResponse.push(r.key);}
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');fs.writeFileSync(new URL('../research/all-parameter-audit.json.gz',import.meta.url),compressed);fs.writeFileSync(new URL('../research/all-parameter-summary.json',import.meta.url),JSON.stringify({fingerprint:x.fingerprint,records:x.records,locked:x.locked,variableScalarsWithResponse:x.rows.filter(r=>r.response).length,sampledOneValuePerAxis:true,groups,rawSHA256:hash(raw),compressedSHA256:hash(compressed),rawBytes:raw.length,compressedBytes:compressed.length,numericalOnly:true,notProofOfSemanticPartCoverageOrVisualAcceptance:true},null,2));console.log({records:x.records,compressedBytes:compressed.length});
